CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, email_verified boolean NOT NULL DEFAULT false, image text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (id text PRIMARY KEY, expires_at timestamptz NOT NULL, token text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ip_address text, user_agent text, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE account (id text PRIMARY KEY, account_id text NOT NULL, provider_id text NOT NULL, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, access_token text, refresh_token text, id_token text, access_token_expires_at timestamptz, refresh_token_expires_at timestamptz, scope text, password text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider_id,account_id));
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX session_user_idx ON session(user_id);
CREATE INDEX verification_identifier_idx ON verification(identifier);
CREATE TABLE staff_profiles(user_id text PRIMARY KEY REFERENCES "user"(id), staff_code text NOT NULL UNIQUE, role text NOT NULL CHECK(role IN ('owner','order_staff','warehouse_staff','content_staff')), active boolean NOT NULL DEFAULT true);
CREATE TABLE customer_profiles(user_id text PRIMARY KEY REFERENCES "user"(id), display_name text NOT NULL, phone text);
CREATE TABLE addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id),recipient text NOT NULL,phone text NOT NULL,province text NOT NULL,ward text NOT NULL,address_line text NOT NULL,is_default boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX address_default_idx ON addresses(user_id) WHERE is_default;
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,slug text NOT NULL UNIQUE,name_vi text NOT NULL,name_en text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid NOT NULL REFERENCES categories(id),slug text NOT NULL UNIQUE,model_code text NOT NULL UNIQUE,business_status text NOT NULL DEFAULT 'active' CHECK(business_status IN ('draft','active','discontinued','archived')),generation text,source_url text NOT NULL,specs jsonb NOT NULL DEFAULT '{}',poster text NOT NULL DEFAULT '/media/phone-burgundy.svg');
CREATE TABLE product_translations(product_id uuid NOT NULL REFERENCES products(id),locale text NOT NULL CHECK(locale IN ('vi','en')),name text NOT NULL,description text NOT NULL,seo_title text NOT NULL,content_status text NOT NULL DEFAULT 'published' CHECK(content_status IN ('draft','published')),PRIMARY KEY(product_id,locale));
CREATE TABLE attribute_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid NOT NULL REFERENCES categories(id),code text NOT NULL,value_type text NOT NULL CHECK(value_type IN ('text','number','boolean','option')),unit text,compare_enabled boolean NOT NULL DEFAULT true,UNIQUE(category_id,code));
CREATE TABLE product_attribute_values(product_id uuid NOT NULL REFERENCES products(id),attribute_id uuid NOT NULL REFERENCES attribute_definitions(id),value_text text,value_number numeric,value_boolean boolean,PRIMARY KEY(product_id,attribute_id),CHECK(num_nonnulls(value_text,value_number,value_boolean)=1));
CREATE TABLE product_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),sku text NOT NULL UNIQUE,option_signature text NOT NULL,options jsonb NOT NULL DEFAULT '{}',price_vnd bigint NOT NULL CHECK(price_vnd>=0),tracking_mode text NOT NULL CHECK(tracking_mode IN ('serialized','quantity')),active boolean NOT NULL DEFAULT true,standard_warranty_months integer NOT NULL DEFAULT 12 CHECK(standard_warranty_months>=0),care_fee_vnd bigint CHECK(care_fee_vnd>=0),UNIQUE(product_id,option_signature),UNIQUE(id,product_id));
CREATE TABLE variant_attribute_values(variant_id uuid NOT NULL REFERENCES product_variants(id),attribute_id uuid NOT NULL REFERENCES attribute_definitions(id),value_text text,value_number numeric,value_boolean boolean,PRIMARY KEY(variant_id,attribute_id),CHECK(num_nonnulls(value_text,value_number,value_boolean)=1));
CREATE TABLE product_compatibilities(accessory_product_id uuid REFERENCES products(id),target_product_id uuid REFERENCES products(id),PRIMARY KEY(accessory_product_id,target_product_id),CHECK(accessory_product_id<>target_product_id));
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),storage_key text NOT NULL UNIQUE,visibility text NOT NULL CHECK(visibility IN ('public','private','staging')),mime text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>0),checksum text NOT NULL,validation_status text NOT NULL CHECK(validation_status IN ('valid','invalid','pending')),source_url text,license_note text,owner_user_id text REFERENCES "user"(id),metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid NOT NULL REFERENCES products(id),variant_id uuid,media_id uuid NOT NULL REFERENCES media_assets(id),position integer NOT NULL,role text NOT NULL,FOREIGN KEY(variant_id,product_id) REFERENCES product_variants(id,product_id));
CREATE TABLE warehouses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE CHECK(code='MAIN'),name text NOT NULL);
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL,contact text NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES suppliers(id),code text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN ('draft','approved','part_received','received','cancelled')),created_by text NOT NULL REFERENCES "user"(id),approved_by text REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id),variant_id uuid NOT NULL REFERENCES product_variants(id),quantity integer NOT NULL CHECK(quantity>0),unit_cost_vnd bigint NOT NULL CHECK(unit_cost_vnd>=0),UNIQUE(id,purchase_order_id));
CREATE TABLE goods_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id),receipt_no text NOT NULL UNIQUE,received_by text NOT NULL REFERENCES "user"(id),received_at timestamptz NOT NULL DEFAULT now(),event_key text NOT NULL UNIQUE,UNIQUE(id,purchase_order_id));
CREATE TABLE goods_receipt_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),receipt_id uuid NOT NULL,purchase_order_id uuid NOT NULL,purchase_order_item_id uuid NOT NULL,received_qty integer NOT NULL CHECK(received_qty>0),unit_cost_vnd bigint NOT NULL CHECK(unit_cost_vnd>=0),FOREIGN KEY(receipt_id,purchase_order_id) REFERENCES goods_receipts(id,purchase_order_id),FOREIGN KEY(purchase_order_item_id,purchase_order_id) REFERENCES purchase_order_items(id,purchase_order_id));
CREATE TABLE inventory_lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),warehouse_id uuid NOT NULL REFERENCES warehouses(id),variant_id uuid NOT NULL REFERENCES product_variants(id),receipt_item_id uuid NOT NULL UNIQUE REFERENCES goods_receipt_items(id),received_at timestamptz NOT NULL DEFAULT now(),unit_cost_vnd bigint NOT NULL CHECK(unit_cost_vnd>=0),qty_on_hand integer NOT NULL CHECK(qty_on_hand>=0),qty_reserved integer NOT NULL DEFAULT 0 CHECK(qty_reserved>=0 AND qty_reserved<=qty_on_hand),UNIQUE(id,variant_id));
CREATE TABLE inventory_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lot_id uuid NOT NULL REFERENCES inventory_lots(id),condition_status text NOT NULL DEFAULT 'new' CHECK(condition_status IN ('new','used','faulty','opened')),custody_status text NOT NULL DEFAULT 'available' CHECK(custody_status IN ('available','reserved','shipped','quarantine','service')),UNIQUE(id,lot_id));
CREATE TABLE inventory_identifiers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inventory_unit_id uuid NOT NULL REFERENCES inventory_units(id),kind text NOT NULL CHECK(kind IN ('serial','imei')),normalized_value text NOT NULL,UNIQUE(kind,normalized_value));
CREATE TABLE promotions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code_normalized text NOT NULL UNIQUE CHECK(code_normalized=upper(trim(code_normalized))),active boolean NOT NULL DEFAULT true,max_uses integer CHECK(max_uses>0),max_uses_per_customer integer CHECK(max_uses_per_customer>0));
CREATE TABLE promotion_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),promotion_id uuid NOT NULL REFERENCES promotions(id),version_no integer NOT NULL CHECK(version_no>0),discount_type text NOT NULL CHECK(discount_type IN ('fixed','percentage')),value bigint NOT NULL CHECK(value>0),max_discount_vnd bigint CHECK(max_discount_vnd>=0),min_purchase_vnd bigint NOT NULL DEFAULT 0 CHECK(min_purchase_vnd>=0),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,all_products boolean NOT NULL DEFAULT true,UNIQUE(promotion_id,version_no),UNIQUE(id,promotion_id),CHECK(starts_at<ends_at),CHECK(discount_type<>'percentage' OR value<=100));
CREATE TABLE promotion_targets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),promotion_version_id uuid NOT NULL REFERENCES promotion_versions(id),variant_id uuid REFERENCES product_variants(id),product_id uuid REFERENCES products(id),category_id uuid REFERENCES categories(id),CHECK(num_nonnulls(variant_id,product_id,category_id)=1));
CREATE TABLE carts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id text NOT NULL UNIQUE REFERENCES "user"(id),applied_promotion_version_id uuid REFERENCES promotion_versions(id),revision integer NOT NULL DEFAULT 0);
CREATE TABLE cart_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cart_id uuid NOT NULL REFERENCES carts(id) ON DELETE CASCADE,variant_id uuid NOT NULL REFERENCES product_variants(id),quantity integer NOT NULL CHECK(quantity>0 AND quantity<=100),care boolean NOT NULL DEFAULT false,UNIQUE(cart_id,variant_id,care));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_no text NOT NULL UNIQUE,customer_id text NOT NULL REFERENCES "user"(id),responsible_staff_id text REFERENCES staff_profiles(user_id),order_status text NOT NULL CHECK(order_status IN ('building','pending','confirmed','handed_off','completed','cancelled','expired','reconciliation')),payment_method text NOT NULL CHECK(payment_method IN ('cod','banking','momo','visa')),address_snapshot jsonb NOT NULL,total_vnd bigint NOT NULL CHECK(total_vnd>=0),currency text NOT NULL DEFAULT 'VND' CHECK(currency='VND'),exchange_rate_vnd numeric NOT NULL DEFAULT 25000 CHECK(exchange_rate_vnd>0),policy_snapshot jsonb NOT NULL DEFAULT '{}',expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,UNIQUE(id,customer_id));
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),line_no integer NOT NULL CHECK(line_no>0),line_type text NOT NULL CHECK(line_type IN ('product','warranty','shipping')),product_id uuid REFERENCES products(id),variant_id uuid,parent_item_id uuid,quantity integer NOT NULL CHECK(quantity>0),unit_price_vnd bigint NOT NULL CHECK(unit_price_vnd>=0),voucher_discount_vnd bigint NOT NULL DEFAULT 0 CHECK(voucher_discount_vnd>=0),points_discount_vnd bigint NOT NULL DEFAULT 0 CHECK(points_discount_vnd>=0),net_amount_vnd bigint NOT NULL CHECK(net_amount_vnd>=0 AND net_amount_vnd=quantity::bigint*unit_price_vnd-voucher_discount_vnd-points_discount_vnd),snapshot jsonb NOT NULL,UNIQUE(order_id,line_no),UNIQUE(id,order_id),FOREIGN KEY(variant_id,product_id) REFERENCES product_variants(id,product_id),FOREIGN KEY(parent_item_id,order_id) REFERENCES order_items(id,order_id),CHECK(line_type<>'product' OR (product_id IS NOT NULL AND variant_id IS NOT NULL)),CHECK((line_type='warranty')=(parent_item_id IS NOT NULL)),CHECK(line_type<>'shipping' OR quantity=1));
CREATE TABLE order_item_unit_amounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_id uuid NOT NULL REFERENCES order_items(id),unit_ordinal integer NOT NULL CHECK(unit_ordinal>0),parent_unit_amount_id uuid REFERENCES order_item_unit_amounts(id),gross_vnd bigint NOT NULL CHECK(gross_vnd>=0),voucher_discount_vnd bigint NOT NULL CHECK(voucher_discount_vnd>=0),redeemed_points integer NOT NULL DEFAULT 0 CHECK(redeemed_points>=0),points_discount_vnd bigint NOT NULL CHECK(points_discount_vnd=redeemed_points::bigint*1000),net_amount_vnd bigint NOT NULL CHECK(net_amount_vnd>=0 AND net_amount_vnd=gross_vnd-voucher_discount_vnd-points_discount_vnd),credit_planned_vnd bigint NOT NULL CHECK(credit_planned_vnd>=0),cash_planned_vnd bigint NOT NULL CHECK(cash_planned_vnd>=0 AND cash_planned_vnd+credit_planned_vnd=net_amount_vnd),UNIQUE(order_item_id,unit_ordinal),UNIQUE(id,order_item_id));
CREATE TABLE promotion_redemptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),promotion_id uuid NOT NULL REFERENCES promotions(id),promotion_version_id uuid NOT NULL,customer_id text NOT NULL REFERENCES "user"(id),order_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('reserved','consumed','released')),amount_vnd bigint NOT NULL CHECK(amount_vnd>=0),expires_at timestamptz NOT NULL,idempotency_key text NOT NULL UNIQUE,UNIQUE(order_id,promotion_id),FOREIGN KEY(promotion_version_id,promotion_id) REFERENCES promotion_versions(id,promotion_id),FOREIGN KEY(order_id,customer_id) REFERENCES orders(id,customer_id));
CREATE TABLE order_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_id uuid NOT NULL REFERENCES order_items(id),kind text NOT NULL CHECK(kind IN ('voucher','points')),promotion_redemption_id uuid REFERENCES promotion_redemptions(id),amount_vnd bigint NOT NULL CHECK(amount_vnd>=0),source_event_key text NOT NULL UNIQUE);
CREATE TABLE inventory_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_id uuid NOT NULL REFERENCES order_items(id),variant_id uuid NOT NULL REFERENCES product_variants(id),quantity integer NOT NULL CHECK(quantity>0),expires_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('active','released','consumed','expired')));
CREATE TABLE inventory_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_id uuid NOT NULL REFERENCES order_items(id),order_item_unit_amount_id uuid NOT NULL,lot_id uuid NOT NULL REFERENCES inventory_lots(id),inventory_unit_id uuid,quantity integer NOT NULL CHECK(quantity>0),cost_vnd bigint NOT NULL CHECK(cost_vnd>=0),state text NOT NULL CHECK(state IN ('reserved','shipped','returned','released','replaced')),FOREIGN KEY(order_item_unit_amount_id,order_item_id) REFERENCES order_item_unit_amounts(id,order_item_id),FOREIGN KEY(inventory_unit_id,lot_id) REFERENCES inventory_units(id,lot_id),CHECK(inventory_unit_id IS NULL OR quantity=1));
CREATE UNIQUE INDEX inventory_unit_active_idx ON inventory_allocations(inventory_unit_id) WHERE inventory_unit_id IS NOT NULL AND state IN ('reserved','shipped');
CREATE UNIQUE INDEX allocation_unit_active_idx ON inventory_allocations(order_item_unit_amount_id) WHERE state IN ('reserved','shipped');
CREATE TABLE stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),variant_id uuid NOT NULL REFERENCES product_variants(id),lot_id uuid NOT NULL,unit_id uuid,quantity_delta integer NOT NULL,kind text NOT NULL CHECK(kind IN ('receive','reserve','release','ship','return','adjust','replacement')),source_event_key text NOT NULL UNIQUE,actor_user_id text REFERENCES "user"(id),reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(lot_id,variant_id) REFERENCES inventory_lots(id,variant_id),FOREIGN KEY(unit_id,lot_id) REFERENCES inventory_units(id,lot_id));
CREATE TABLE payment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),method text NOT NULL CHECK(method IN ('cod','banking','momo','visa')),status text NOT NULL CHECK(status IN ('pending','success','failed','cancelled','expired','reconciliation')),requested_amount_vnd bigint NOT NULL CHECK(requested_amount_vnd>0),request_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,order_id));
CREATE TABLE payment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_attempt_id uuid NOT NULL REFERENCES payment_attempts(id),event_key text NOT NULL UNIQUE,event_type text NOT NULL,payload_digest text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),payment_attempt_id uuid,tender_kind text NOT NULL CHECK(tender_kind IN ('cash_demo','store_credit')),amount_vnd bigint NOT NULL CHECK(amount_vnd>0),received_at timestamptz NOT NULL DEFAULT now(),source_event_key text NOT NULL UNIQUE,FOREIGN KEY(payment_attempt_id,order_id) REFERENCES payment_attempts(id,order_id),UNIQUE(id,order_id));
CREATE TABLE order_tender_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_unit_amount_id uuid NOT NULL REFERENCES order_item_unit_amounts(id),receipt_id uuid NOT NULL REFERENCES payment_receipts(id),amount_vnd bigint NOT NULL CHECK(amount_vnd>0),UNIQUE(receipt_id,order_item_unit_amount_id));
CREATE TABLE shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),tracking_no text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN ('handed_off','in_transit','delivered','failed','returned','closed')),retry_of uuid REFERENCES shipments(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,order_id));
CREATE TABLE shipment_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shipment_id uuid NOT NULL REFERENCES shipments(id),status text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now(),event_key text NOT NULL UNIQUE);
CREATE TABLE loyalty_accounts(user_id text PRIMARY KEY REFERENCES "user"(id),balance_points integer NOT NULL DEFAULT 0,net_spend_vnd bigint NOT NULL DEFAULT 0 CHECK(net_spend_vnd>=0));
CREATE TABLE store_credit_accounts(user_id text PRIMARY KEY REFERENCES "user"(id),balance_vnd bigint NOT NULL DEFAULT 0 CHECK(balance_vnd>=0));
CREATE TABLE benefit_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id text NOT NULL REFERENCES "user"(id),order_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('points','store_credit')),amount bigint NOT NULL CHECK(amount>0),expires_at timestamptz NOT NULL,status text NOT NULL CHECK(status IN ('active','consumed','released')),FOREIGN KEY(order_id,customer_id) REFERENCES orders(id,customer_id));
CREATE UNIQUE INDEX benefit_hold_active_idx ON benefit_holds(order_id,kind) WHERE status='active';
CREATE SEQUENCE invoice_number_seq;
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_no text UNIQUE,order_id uuid NOT NULL UNIQUE REFERENCES orders(id),lifecycle text NOT NULL CHECK(lifecycle IN ('draft','issued')),issued_at timestamptz,customer_id text NOT NULL REFERENCES "user"(id),responsible_staff_id text REFERENCES staff_profiles(user_id),issued_by_user_id text REFERENCES "user"(id),currency text NOT NULL DEFAULT 'VND' CHECK(currency='VND'),subtotal_vnd bigint NOT NULL CHECK(subtotal_vnd>=0),discount_total_vnd bigint NOT NULL CHECK(discount_total_vnd>=0),grand_total_vnd bigint NOT NULL CHECK(grand_total_vnd>=0 AND grand_total_vnd=subtotal_vnd-discount_total_vnd),customer_snapshot jsonb NOT NULL,staff_snapshot jsonb NOT NULL,UNIQUE(id,order_id),FOREIGN KEY(order_id,customer_id) REFERENCES orders(id,customer_id),CHECK(lifecycle<>'issued' OR (invoice_no IS NOT NULL AND issued_at IS NOT NULL AND responsible_staff_id IS NOT NULL AND issued_by_user_id IS NOT NULL)));
CREATE TABLE invoice_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_id uuid NOT NULL,order_id uuid NOT NULL,order_item_id uuid NOT NULL UNIQUE,line_no integer NOT NULL CHECK(line_no>0),line_type text NOT NULL CHECK(line_type IN ('product','warranty','shipping')),product_id uuid REFERENCES products(id),variant_id uuid,parent_invoice_item_id uuid,sku_snapshot text NOT NULL,name_snapshot text NOT NULL,variant_snapshot jsonb NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price_vnd bigint NOT NULL CHECK(unit_price_vnd>=0),voucher_discount_vnd bigint NOT NULL CHECK(voucher_discount_vnd>=0),points_discount_vnd bigint NOT NULL CHECK(points_discount_vnd>=0),net_amount_vnd bigint NOT NULL CHECK(net_amount_vnd>=0 AND net_amount_vnd=quantity::bigint*unit_price_vnd-voucher_discount_vnd-points_discount_vnd),UNIQUE(invoice_id,line_no),UNIQUE(id,invoice_id),FOREIGN KEY(invoice_id,order_id) REFERENCES invoices(id,order_id),FOREIGN KEY(order_item_id,order_id) REFERENCES order_items(id,order_id),FOREIGN KEY(parent_invoice_item_id,invoice_id) REFERENCES invoice_items(id,invoice_id),FOREIGN KEY(variant_id,product_id) REFERENCES product_variants(id,product_id),CHECK(line_type<>'product' OR (product_id IS NOT NULL AND variant_id IS NOT NULL)),CHECK((line_type='warranty')=(parent_invoice_item_id IS NOT NULL)),CHECK(line_type<>'shipping' OR quantity=1));
CREATE TABLE return_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL,customer_id text NOT NULL,state text NOT NULL CHECK(state IN ('requested','approved','received','inspected','rejected','credited','closed')),reason text NOT NULL CHECK(reason IN ('defective','wrong_item')),created_at timestamptz NOT NULL DEFAULT now(),inspection_result text,inspected_by text REFERENCES "user"(id),inspected_at timestamptz,fee_vnd bigint NOT NULL DEFAULT 30000 CHECK(fee_vnd>=0),FOREIGN KEY(order_id,customer_id) REFERENCES orders(id,customer_id),UNIQUE(id,order_id));
CREATE TABLE return_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),return_request_id uuid NOT NULL,order_id uuid NOT NULL,order_item_id uuid NOT NULL,qty integer NOT NULL CHECK(qty>0),actual_received_identifier text,FOREIGN KEY(return_request_id,order_id) REFERENCES return_requests(id,order_id),FOREIGN KEY(order_item_id,order_id) REFERENCES order_items(id,order_id),UNIQUE(id,order_item_id));
CREATE TABLE return_item_units(return_item_id uuid NOT NULL,order_item_id uuid NOT NULL,order_item_unit_amount_id uuid NOT NULL,inventory_unit_id uuid REFERENCES inventory_units(id),PRIMARY KEY(return_item_id,order_item_unit_amount_id),FOREIGN KEY(return_item_id,order_item_id) REFERENCES return_items(id,order_item_id),FOREIGN KEY(order_item_unit_amount_id,order_item_id) REFERENCES order_item_unit_amounts(id,order_item_id));
CREATE TABLE warranty_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE warranty_plan_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),plan_id uuid NOT NULL REFERENCES warranty_plans(id),version_no integer NOT NULL,term_months integer NOT NULL CHECK(term_months=12),fee_vnd bigint NOT NULL CHECK(fee_vnd>=0),policy_snapshot jsonb NOT NULL,UNIQUE(plan_id,version_no));
CREATE TABLE warranty_entitlements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_item_unit_amount_id uuid NOT NULL UNIQUE REFERENCES order_item_unit_amounts(id),plan_version_id uuid NOT NULL REFERENCES warranty_plan_versions(id),inventory_unit_id uuid REFERENCES inventory_units(id),starts_on date,ends_on date,state text NOT NULL CHECK(state IN ('pending','active','cancelled','expired','refunded')),used boolean NOT NULL DEFAULT false,CHECK(ends_on IS NULL OR starts_on<ends_on));
CREATE TABLE warranty_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entitlement_id uuid NOT NULL REFERENCES warranty_entitlements(id),state text NOT NULL CHECK(state IN ('requested','received','inspected','repairing','repaired','replace','replaced','refund','refunded','rejected','closed')),description text NOT NULL,damage_kind text NOT NULL CHECK(damage_kind IN ('hardware','accidental','liquid')),inspection_result text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warranty_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_id uuid NOT NULL REFERENCES warranty_claims(id),actor_id text NOT NULL REFERENCES "user"(id),event text NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warranty_replacements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),claim_id uuid NOT NULL UNIQUE REFERENCES warranty_claims(id),old_unit_id uuid NOT NULL REFERENCES inventory_units(id),new_unit_id uuid NOT NULL UNIQUE REFERENCES inventory_units(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(old_unit_id<>new_unit_id));
CREATE TABLE credit_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),credit_note_no text NOT NULL UNIQUE,invoice_id uuid NOT NULL,order_id uuid NOT NULL,status text NOT NULL CHECK(status IN ('draft','issued')),issued_at timestamptz,return_request_id uuid,warranty_claim_id uuid REFERENCES warranty_claims(id),shipment_id uuid,reason text NOT NULL,total_vnd bigint NOT NULL CHECK(total_vnd>=0),approved_by_user_id text NOT NULL REFERENCES "user"(id),event_key text NOT NULL UNIQUE,UNIQUE(id,order_id),FOREIGN KEY(invoice_id,order_id) REFERENCES invoices(id,order_id),FOREIGN KEY(return_request_id,order_id) REFERENCES return_requests(id,order_id),FOREIGN KEY(shipment_id,order_id) REFERENCES shipments(id,order_id),CHECK(num_nonnulls(return_request_id,warranty_claim_id,shipment_id)=1),CHECK(status<>'issued' OR issued_at IS NOT NULL));
CREATE TABLE credit_note_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),credit_note_id uuid NOT NULL REFERENCES credit_notes(id),invoice_item_id uuid NOT NULL REFERENCES invoice_items(id),quantity integer CHECK(quantity>0),amount_vnd bigint NOT NULL CHECK(amount_vnd>=0),CHECK(quantity>0 OR amount_vnd>0),UNIQUE(id,invoice_item_id));
CREATE TABLE credit_note_item_units(credit_note_item_id uuid NOT NULL REFERENCES credit_note_items(id),order_item_unit_amount_id uuid NOT NULL REFERENCES order_item_unit_amounts(id),amount_vnd bigint NOT NULL CHECK(amount_vnd>=0),PRIMARY KEY(credit_note_item_id,order_item_unit_amount_id));
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),credit_note_id uuid,status text NOT NULL CHECK(status IN ('approved','pending','completed','failed')),amount_vnd bigint NOT NULL CHECK(amount_vnd>0),approved_by text NOT NULL REFERENCES "user"(id),completed_at timestamptz,idempotency_key text NOT NULL UNIQUE,FOREIGN KEY(credit_note_id,order_id) REFERENCES credit_notes(id,order_id),CHECK(status<>'completed' OR completed_at IS NOT NULL));
CREATE TABLE refund_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),refund_id uuid NOT NULL REFERENCES refunds(id),payment_receipt_id uuid NOT NULL REFERENCES payment_receipts(id),order_item_unit_amount_id uuid NOT NULL REFERENCES order_item_unit_amounts(id),amount_vnd bigint NOT NULL CHECK(amount_vnd>0),UNIQUE(refund_id,payment_receipt_id,order_item_unit_amount_id));
CREATE TABLE trade_in_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id text NOT NULL REFERENCES "user"(id),reception_method text NOT NULL CHECK(reception_method IN ('store','remote')),state text NOT NULL CHECK(state IN ('requested','received','inspected','quoted','contact_pending','completed','returned','exception')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trade_in_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES trade_in_requests(id),product_id uuid NOT NULL REFERENCES products(id),variant_id uuid,qty integer NOT NULL CHECK(qty>0),identifier text,internal_code text NOT NULL UNIQUE,condition_snapshot jsonb NOT NULL,state text NOT NULL CHECK(state IN ('requested','received','inspected','quoted','accepted','rejected','completed','returned','exception')),inventory_unit_id uuid REFERENCES inventory_units(id),FOREIGN KEY(variant_id,product_id) REFERENCES product_variants(id,product_id),UNIQUE(id,request_id));
CREATE UNIQUE INDEX trade_in_identifier_active_idx ON trade_in_items(identifier) WHERE identifier IS NOT NULL AND state NOT IN ('completed','returned','rejected');
CREATE TABLE trade_in_inspections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),item_id uuid NOT NULL REFERENCES trade_in_items(id),inspector_staff_id text NOT NULL REFERENCES staff_profiles(user_id),checklist_version integer NOT NULL,assessed_condition jsonb NOT NULL,inspected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trade_in_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES trade_in_requests(id),version_no integer NOT NULL,expires_at timestamptz NOT NULL,quoted_by text NOT NULL REFERENCES "user"(id),approved_by text REFERENCES "user"(id),UNIQUE(request_id,version_no),UNIQUE(id,request_id));
CREATE TABLE trade_in_quote_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),quote_id uuid NOT NULL,request_id uuid NOT NULL,item_id uuid NOT NULL,offered_vnd bigint NOT NULL CHECK(offered_vnd>0),decision text NOT NULL CHECK(decision IN ('pending','accepted','rejected')),decided_at timestamptz,FOREIGN KEY(quote_id,request_id) REFERENCES trade_in_quotes(id,request_id),FOREIGN KEY(item_id,request_id) REFERENCES trade_in_items(id,request_id),UNIQUE(quote_id,item_id));
CREATE TABLE trade_in_shipments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid NOT NULL REFERENCES trade_in_requests(id),direction text NOT NULL CHECK(direction IN ('inbound','outbound')),tracking_no text NOT NULL UNIQUE,fee_vnd bigint NOT NULL CHECK(fee_vnd>=0),state text NOT NULL CHECK(state IN ('created','in_transit','delivered','exception')));
CREATE TABLE store_credit_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id text NOT NULL REFERENCES store_credit_accounts(user_id),delta_vnd bigint NOT NULL CHECK(delta_vnd<>0),kind text NOT NULL CHECK(kind IN ('trade_in','spend','refund')),trade_in_item_id uuid REFERENCES trade_in_items(id),quote_item_id uuid REFERENCES trade_in_quote_items(id),order_id uuid REFERENCES orders(id),refund_id uuid REFERENCES refunds(id),event_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='trade_in' AND trade_in_item_id IS NOT NULL AND quote_item_id IS NOT NULL AND order_id IS NULL AND refund_id IS NULL AND delta_vnd>0) OR (kind='spend' AND order_id IS NOT NULL AND trade_in_item_id IS NULL AND refund_id IS NULL AND delta_vnd<0) OR (kind='refund' AND refund_id IS NOT NULL AND order_id IS NOT NULL AND trade_in_item_id IS NULL AND delta_vnd>0)));
CREATE UNIQUE INDEX trade_in_credit_once ON store_credit_entries(trade_in_item_id) WHERE kind='trade_in';
CREATE TABLE loyalty_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id text NOT NULL REFERENCES loyalty_accounts(user_id),delta integer NOT NULL CHECK(delta<>0),kind text NOT NULL CHECK(kind IN ('earn','redeem','restore','reverse')),order_id uuid NOT NULL REFERENCES orders(id),unit_id uuid REFERENCES order_item_unit_amounts(id),event_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE return_evidence(return_request_id uuid REFERENCES return_requests(id),media_id uuid REFERENCES media_assets(id),PRIMARY KEY(return_request_id,media_id));
CREATE TABLE trade_in_evidence(inspection_id uuid REFERENCES trade_in_inspections(id),media_id uuid REFERENCES media_assets(id),PRIMARY KEY(inspection_id,media_id));
CREATE TABLE warranty_evidence(claim_id uuid REFERENCES warranty_claims(id),media_id uuid REFERENCES media_assets(id),PRIMARY KEY(claim_id,media_id));
CREATE TABLE landing_pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE);
CREATE TABLE landing_drafts(page_id uuid PRIMARY KEY REFERENCES landing_pages(id),revision integer NOT NULL DEFAULT 0,sections jsonb NOT NULL,updated_by text REFERENCES "user"(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE landing_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),page_id uuid NOT NULL REFERENCES landing_pages(id),version_no integer NOT NULL,sections jsonb NOT NULL,created_by text NOT NULL REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(page_id,version_no),UNIQUE(id,page_id));
CREATE TABLE landing_publications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),page_id uuid NOT NULL,version_id uuid NOT NULL,published_by text NOT NULL REFERENCES "user"(id),published_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(version_id,page_id) REFERENCES landing_versions(id,page_id));
CREATE TABLE landing_media_refs(landing_version_id uuid REFERENCES landing_versions(id),media_id uuid REFERENCES media_assets(id),PRIMARY KEY(landing_version_id,media_id));
CREATE TABLE app_settings(key text PRIMARY KEY,value jsonb NOT NULL,version integer NOT NULL DEFAULT 1);
CREATE TABLE setting_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key text NOT NULL REFERENCES app_settings(key),version_no integer NOT NULL,value jsonb NOT NULL,changed_by text REFERENCES "user"(id),changed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(key,version_no));
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),recipient_user_id text NOT NULL REFERENCES "user"(id),type text NOT NULL,message text NOT NULL,entity_id uuid,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id text REFERENCES "user"(id),action text NOT NULL,entity_type text NOT NULL,entity_id text,before_data jsonb,after_data jsonb,reason text,occurred_at timestamptz NOT NULL DEFAULT now(),correlation_id text);
CREATE TABLE idempotency_records(scope text NOT NULL,key text NOT NULL,request_hash text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(scope,key));
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_key text NOT NULL UNIQUE,type text NOT NULL,payload jsonb NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','completed','failed')),attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoice_exports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requested_by_user_id text NOT NULL REFERENCES "user"(id),query_json jsonb NOT NULL,read_at timestamptz NOT NULL,row_count integer NOT NULL CHECK(row_count>=0),total_vnd bigint NOT NULL,status text NOT NULL CHECK(status IN ('building','ready','failed')),expires_at timestamptz NOT NULL,file_manifest jsonb NOT NULL DEFAULT '{}',role_snapshot text NOT NULL);
CREATE TABLE wishlists(user_id text REFERENCES "user"(id),product_id uuid REFERENCES products(id),PRIMARY KEY(user_id,product_id));
CREATE TABLE stock_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lot_id uuid NOT NULL REFERENCES inventory_lots(id),quantity_delta integer NOT NULL CHECK(quantity_delta<>0),reason text NOT NULL,requested_by text NOT NULL REFERENCES "user"(id),approved_by text REFERENCES "user"(id),status text NOT NULL CHECK(status IN ('requested','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX invoices_issued_idx ON invoices(issued_at,id) WHERE lifecycle='issued';
CREATE INDEX invoices_staff_idx ON invoices(responsible_staff_id,issued_at,id);
CREATE INDEX invoices_customer_idx ON invoices(customer_id,issued_at,id);
CREATE INDEX invoice_items_invoice_idx ON invoice_items(invoice_id);
CREATE INDEX invoice_items_product_idx ON invoice_items(product_id,invoice_id);
CREATE INDEX invoice_items_variant_idx ON invoice_items(variant_id,invoice_id);
CREATE INDEX credit_notes_invoice_idx ON credit_notes(invoice_id,issued_at);
CREATE INDEX credit_note_items_original_idx ON credit_note_items(invoice_item_id);
CREATE INDEX orders_customer_idx ON orders(customer_id,created_at);
CREATE INDEX lots_fifo_idx ON inventory_lots(variant_id,received_at,id);
CREATE INDEX reservations_expiry_idx ON inventory_reservations(status,expires_at);
CREATE INDEX redemptions_quota_idx ON promotion_redemptions(promotion_id,status,customer_id);
CREATE VIEW variant_stock AS SELECT v.id AS variant_id,CASE WHEN v.tracking_mode='serialized' THEN (SELECT count(*) FROM inventory_units u JOIN inventory_lots l ON l.id=u.lot_id WHERE l.variant_id=v.id AND u.custody_status='available' AND u.condition_status='new') ELSE COALESCE((SELECT sum(qty_on_hand-qty_reserved) FROM inventory_lots l WHERE l.variant_id=v.id),0) END AS available FROM product_variants v;
